```python
def run_in_executor(self, executor, func, *args):
    """Runs a function in a ``concurrent.futures.Executor``. If
    ``executor`` is ``None``, the IO loop's default executor will be used.

    Use `functools.partial` to pass keyword arguments to `func`.
    """
    if ThreadPoolExecutor is None:
        raise RuntimeError(
            "concurrent.futures is required to use IOLoop.run_in_executor")

    if not callable(func):
        raise ValueError("The provided function must be callable.")

    if executor is None:
        if not hasattr(self, '_executor'):
            from tornado.process import cpu_count
            self._executor = ThreadPoolExecutor(max_workers=(cpu_count() * 5))
        executor = self._executor

    future = executor.submit(func, *args)
    tornado_future = Future()  # Create a Tornado Future

    def callback(f):
        if f.cancelled():
            tornado_future.cancel()
        elif f.done():
            try:
                result = f.result()  # This may raise an exception
                tornado_future.set_result(result)
            except Exception as e:
                tornado_future.set_exception(e)

    future.add_done_callback(callback)
    return tornado_future
```
